import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode="fast", level="3".

    keys[i] is set to values[i]; if a key repeats, the last value wins.
    Returns the resulting values ordered: mode, level, then every other
    key in order of its first appearance in keys.

    Raises ValueError if keys and values have different lengths.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    result: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        result[k] = v
    return list(result.values())


def test_defaults_only() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_level_only() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_override_mode_only() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_both() -> None:
    assert settings(["mode", "level"], ["slow", "1"]) == ["slow", "1"]


def test_given_order_of_mode_and_level_ignored() -> None:
    assert settings(["level", "mode"], ["9", "slow"]) == ["slow", "9"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["x", "mode", "y"], ["1", "slow", "2"]) == [
        "slow",
        "3",
        "1",
        "2",
    ]


def test_duplicate_key_last_value_first_position() -> None:
    assert settings(["x", "y", "x"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_duplicate_mode() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_empty_string_values() -> None:
    assert settings(["x", "level"], ["", ""]) == ["fast", "", ""]


def test_length_mismatch() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings([], ["1"])
